def obfuscate_sql_payload(payload):
    # Replaces specific characters with their hexcode alternatives
    obfuscated = ""
    using_char_char = ["a", "e", "g", "s", "m", "r"]
    using_hex_char = ["b", "c", "d", "m", "g", "h", "i", "j", "k", "l", "w", "n", "o", "p", "q", "r", "s", "y", "u", "v", "x", "z"]

    for char in payload:
        if char.lower() in using_char_char:
            obfuscated += "CHAR(" + str(ord(char)) + ")"
        elif char.lower() in using_hex_char:
            obfuscated += "0x" + make_hex(char)
        else:
            obfuscated += char

    # Replaces 'OR' with 'LIKE' and specific hexcode replacements
    obfuscated = obfuscated.replace("OR", "LIKE")
    obfuscated = obfuscated.replace("EO", "PGCD")
    obfuscated = obfuscated.replace("ALH", "&&")
    obfuscated = obfuscated.replace("=", " PGCD ")

    return obfuscated

def make_hex(char):
    return hex(ord(char))[2:]
